#!/usr/bin/env python3
"""Собирает учебник из объясняющих глав и актуальных канонических документов проекта."""
from pathlib import Path, PurePosixPath
import hashlib, re, shutil
R=Path(__file__).resolve().parents[1]; B=R/'book'; C=B/'chapters'
BASE='https://github.com/i1yxaluk-del/Newbie/blob/main/'

def links(text, src):
    base=PurePosixPath(src).parent
    def repl(m):
        label,target=m.group(1),m.group(2)
        if target.startswith(('http://','https://','#','mailto:')): return m.group(0)
        path=str((base/target.split('#')[0]))
        # Нормализуем ../ без обращения к файловой системе.
        parts=[]
        for x in PurePosixPath(path).parts:
            if x=='..':
                if parts: parts.pop()
            elif x!='.': parts.append(x)
        anchor=('#'+target.split('#',1)[1]) if '#' in target else ''
        return f'[{label}]({BASE}{"/".join(parts)}{anchor})'
    return re.sub(r'\[([^\]]+)\]\(([^)]+)\)',repl,text)

def source(path):
    p=R/path
    raw=p.read_text(encoding='utf-8-sig')
    digest=hashlib.sha256(raw.encode()).hexdigest()[:16]
    if p.suffix.lower()=='.md':
        body=links(raw,path)
        body=re.sub(r'(?m)^(#{1,5}) ',lambda m:'#'+m.group(1)+' ',body)
    else:
        lang={'.py':'python','.sh':'bash','.yml':'yaml','.yaml':'yaml','.json':'json','.js':'javascript'}.get(p.suffix,'text')
        body=f'```{lang}\n{raw}\n```'
    return f'\n## Материал проекта: `{path}`\n\n<!-- SOURCE {path} {digest} -->\n\n{body}\n'

def chapter(filename,title,intro,files):
    text=f'# {title}\n\n{intro.strip()}\n\n## Как работать с материалом\n\nСначала прочитайте объяснение главы. Затем откройте перечисленные файлы в рабочем репозитории и сопоставьте текст с текущим кодом. Команды изменения выполняйте на учебной среде. Разделы ниже включены полностью, поэтому глава одновременно служит учебником и справочником.\n'
    for f in files: text+=source(f)
    text+='\n## Практический результат\n\nПерескажите цепочку своими словами, выполните безопасную лабораторную работу и сохраните команды без секретов, фактический результат и способ отката. Если результат отличается от текста, остановитесь: сначала исправляется расхождение, а не подгоняется отчёт.\n'
    (C/filename).write_text(text,encoding='utf-8')

if C.exists(): shutil.rmtree(C)
C.mkdir(parents=True)
chapters=[
('00-сервис-система-и-роль-владельца.md','MSPShield как услуга, система и бизнес', '''MSPShield — не отдельная программа. Это связка людей, договора, инфраструктуры, кода и ежедневной работы. Клиент покупает контролируемый результат: обращения не теряются, состояние систем видно, резервные копии проверяются восстановлением, а границы ответственности записаны.

Смотрите на проект через три потока. Первый — ценность: контакт превращается в договор и обслуживаемого клиента. Второй — техника: запрос идёт через DNS, Caddy и backend к MongoDB и внешним каналам. Третий — управление: метрики превращаются в оповещение, задачу, действие и отчёт. Ошибка возникает, когда один поток принимают за другой: зелёный график не равен выполненному SLA, а подписанный договор не равен технической готовности.

Владелец отвечает не за ручное выполнение каждой команды, а за согласование обещаний с реальной ёмкостью. Он должен понимать зависимости достаточно глубоко, чтобы остановить опасное изменение, проверить восстановление, рассчитать цену и принять решение о найме.''',['README.md','docs/NAVIGATION.md','docs/PROJECT_8_OF_10.md']),
('01-архитектура-и-путь-запроса.md','Архитектура: от браузера до данных и оповещения', '''Начните с конкретного события — посетитель отправил форму. DNS возвращает адрес VM. Caddy завершает TLS и передаёт HTTP-запрос на backend, опубликованный только на `127.0.0.1:8001`. Backend проверяет данные и согласие, пишет заявку в MongoDB и создаёт задание устойчивой очереди. Обработчик доставляет письмо и карточку Kaiten. Повтор доставки допустим, потеря заявки — нет.

Отдельная цепочка следит за первой: exporters отдают показатели, Prometheus забирает их, правила создают alert, Alertmanager группирует его и вызывает MAX webhook. Это разные контуры с разными отказами. Health endpoint показывает только заранее определённую проверку; он не доказывает путь пользователя целиком.

Читая Compose, для каждого сервиса найдите образ, сеть, том, переменные, опубликованные порты, healthcheck и зависимые сервисы. Затем нарисуйте, какие данные переживают пересоздание контейнера.''',['deploy/yandex/README.md','deploy/yandex/docker-compose.yml','deploy/yandex/Caddyfile']),
('02-git-разработка-и-проверки.md','Разработка: Git, backend, frontend, тесты и Pull Request', '''Git хранит историю решений. Коммит должен отвечать на вопрос «что изменилось и зачем», а Pull Request — показывать риск, проверку и возврат. `git status` и `git diff` ничего не меняют; они дают исходные данные перед действием. Секреты, клиентские данные и локальные `.env` в историю не попадают.

Backend — серверная часть на Python. Frontend — код, который собирается и выполняется в браузере. Изменение формы считается законченным только после проверки браузера, API, базы и интеграций. Тест функции не доказывает работу production, а успешная сборка интерфейса не доказывает отправку заявки.

Маршрут разработчика: найти источник истины, создать ветку, изменить один связный участок, прогнать профильные тесты, посмотреть итоговую конфигурацию, открыть PR и выполнить проверку после развёртывания.''',['docs/NAVIGATION.md','docs/training/JUNIOR_OPERATIONS_GUIDE.md','backend/.env.example','frontend/package.json','frontend/.env.example']),
('03-yandex-cloud-и-развертывание.md','Yandex Cloud и полное развёртывание VM', '''Облако предоставляет каталог, сеть, подсеть, адрес, диск и виртуальную машину. Эти сущности живут отдельно: удаление VM не гарантирует удаление диска, снимка или постоянного IP. Группа безопасности фильтрует трафик на уровне облака, `ufw` — внутри Linux, а слушающий сокет принадлежит конкретному процессу.

Развёртывание проходит воротами: подготовка VM, новый набор секретов, preflight, application stack, monitoring stack, Caddy, внутренние проверки, внешний TCP/TLS/HTTP, тестовый P1 и восстановление. DNS меняют последним. Команда, которая завершилась без ошибки, подтверждает только собственный шаг.

`cloud-init` готовит базовую систему при первом запуске, но не является доказательством готовности приложения. Перед закрытием публичного SSH проверяют AWG во второй сессии и аварийный путь возврата.''',['docs/deployment/README.md','docs/deployment/DEPLOY_RUNBOOK.md','docs/deployment/DEPLOYMENT_LESSONS.md','deploy/yandex/cloud-init.yaml']),
('04-linux-сеть-и-диагностика.md','Linux, сеть и поиск неисправности по слоям', '''В Linux программа существует как процесс, слушающий сокет и пишущий журнал. `systemd` управляет службами хоста; Docker управляет контейнерами. Перезапуск Caddy через `systemctl` и пересоздание backend через Compose — разные действия.

Диагностика идёт от наблюдения к изменению: версия и конфигурация, процессы, сокеты, DNS, TCP, TLS, HTTP, приложение, база, внешняя интеграция. `ping` не проверяет TCP. Ответ 200 не доказывает запись в базу. `docker compose restart` не перечитывает изменённый `.env`.

Три частых сетевых результата: timeout — ответ не пришёл; refused — узел достижим, но порт никто не слушает или отклоняет; HTTP 5xx — соединение состоялось, ошибка выше сетевого слоя.''',['docs/deployment/troubleshooting.md','scripts/deployment/preflight.sh']),
('05-backend-база-и-outbox.md','Backend, MongoDB и устойчивая доставка заявки', '''FastAPI сопоставляет метод и путь с функцией. Pydantic проверяет форму данных. Middleware выполняет общие проверки, например обязательное согласие. MongoDB хранит заявку как документ. Индекс ускоряет поиск и может обеспечивать уникальность ключа.

Главная бизнес-гарантия: временный отказ Kaiten или почты не должен удалить уже принятую заявку. Поэтому запись заявки и запись задания outbox выполняются в локальной базе, а внешняя доставка идёт отдельно с повторами. Семантика at-least-once означает «как минимум один раз»: получатель обязан переживать повтор без второго бизнес-результата.

Проверяйте четыре состояния: HTTP-ответ, документ заявки, запись outbox и подтверждённый результат внешнего канала. Только их сочетание описывает полный путь.''',['backend/secure_server.py','backend/server.py','backend/integrations/kaiten.py','backend/integrations/email.py']),
('06-frontend-форма-и-согласие.md','Frontend, форма, согласие и SmartCaptcha', '''Браузер нельзя считать доверенной стороной. Проверка поля в интерфейсе помогает пользователю, но запрос можно отправить напрямую. Поэтому backend повторно проверяет обязательные поля, формат и явное согласие.

Сборка frontend превращает исходники в статические файлы. Переменные, попавшие в браузерный bundle, видны пользователю и не могут быть секретами. Решение SmartCaptcha при отказе должно быть явным: fail-open пропускает запрос без проверки, fail-closed останавливает его. Для production выбран безопасный режим, но нужно следить, чтобы недоступность CAPTCHA не стала незаметной потерей лидов.

Тест формы включает успешную отправку, отсутствие согласия, повреждённый JSON, отказ CAPTCHA, повтор и недоступную интеграцию.''',['frontend/package.json','frontend/.env.example','docs/PROJECT_8_OF_10.md']),
('07-monitoring-prometheus-max.md','Мониторинг, Alertmanager и MAX', '''Метрика — число во времени. Prometheus забирает метрики с targets. Правило превращает условие в alert. Alertmanager группирует события и выбирает получателя. MAX alerter принимает webhook на внутреннем порту 9095 и отправляет сообщение через пользовательскую сессию `pymax`.

MAX-контур требует ручной авторизации. Файл `/session/max.db` равен учётным данным и должен переживать перезагрузку через bind mount. Проверка `auth` без `--authorize` не должна инициировать SMS. Health сервиса не доказывает доставку сообщения; нужен тестовый alert и подтверждение в чате.

Monitoring 24/7 означает постоянный сбор и правила, но не круглосуточную реакцию человека. Окно реакции появляется только в договоре и при наличии ротации.''',['docs/MAX_SETUP.md','services/max_alerter/README.md','deploy/yandex/monitoring/docker-compose.yml','deploy/yandex/monitoring/alertmanager/alertmanager.yml.tmpl']),
('08-почта-postbox-stalwart.md','Почта: Postbox, Stalwart, SMTP и DNS', '''SMTP передаёт письмо. Postbox выполняет внешнюю отправку. Stalwart нужен в mail-профиле как локальный почтовый сервис и хранит конфигурацию и данные в отдельных томах. Пустой `stalwart-data` после переноса запускает режим первичной настройки и не означает успешное восстановление.

SPF перечисляет разрешённые источники отправки. DKIM подписывает письмо; для Postbox публикуется CNAME из консоли. DMARC задаёт политику для получателя. Эти записи повышают доверие, но не обещают попадание во «Входящие».

Ошибка 535 относится к авторизации SMTP. `identity not verified` относится к отправителю или DNS. Исправление начинается с полного ответа сервера и состояния очереди, а не со случайной смены пароля.''',['deploy/yandex/STALWART_RELAY_MODE.md','technical/0_Common/SERVICES/mail_dns.md','docs/deployment/DEPLOY_RUNBOOK.md']),
('09-backup-restore-migration.md','Резервные копии, восстановление и перенос VM', '''Backup — сохранённый набор данных. Restore — получение работающего состояния из копии. RPO показывает допустимую потерю последних данных, RTO — допустимое время восстановления. Эти значения измеряются упражнением, а не назначаются по желанию.

Набор MSPShield включает логический dump MongoDB, Vaultwarden, оба тома Stalwart и MAX session. Старые `.env` не переносятся как облачные учётные данные: на новой VM создаются новые секреты и ключи.

Перенос проходит стадии inventory, backup, новая VM, restore, внутренние проверки, P1, clean-room restore, внешний scan и DNS switch. Старую VM сохраняют выключенной до окончания наблюдения.''',['migration/README.md','docs/deployment/MIGRATION_RUNBOOK.md','docs/deployment/disaster_recovery.md']),
('10-инциденты-runbook-и-postmortem.md','Инцидент: важность, инструкция, подтверждение и разбор', '''Инцидент — нарушение или угроза услуге. Severity задаёт бизнес-влияние и порядок реакции. Runbook применяется только после проверки триггера. Сначала ограничивают ущерб и восстанавливают услугу, затем ищут корневую причину, если поиск не мешает восстановлению.

Хронология содержит время наблюдения, решение, действие и результат. Клиент получает факты, влияние, следующий срок обновления и временную меру — без догадок. Postmortem не ищет виновного; он создаёт проверяемое изменение: тест, алерт, ограничение или обновлённую инструкцию.

Runbook не отменяет мышление: неожиданное состояние — стоп и эскалация, а не импровизация в production.''',['docs/runbooks/README.md','docs/runbooks/R-01.md','docs/runbooks/R-02.md','docs/runbooks/R-03.md']),
('11-жизненный-цикл-клиента.md','Клиент: от Won до offboarding', '''Продажа заканчивается подписанием и оплатой. После этого начинается передача в onboarding. Сначала фиксируются периметр, владельцы, доступы, окно изменений, исходные риски и критерии приёмки. Секреты хранятся в Vaultwarden, задачи и решения — в Kaiten, код — в Git, метрики — в Prometheus.

Steady state — регулярная работа после приёмки: обращения, изменения, проверки, отчёт и обсуждение рисков. Удержание клиента строится не на частых сообщениях, а на видимом результате: меньше неизвестных рисков, проверенное восстановление, понятные изменения и отсутствие сюрпризов в счёте.

Offboarding — часть услуги. Доступы отзываются, данные передаются или удаляются по договору, ключи ротируются, а результат подписывается.''',['docs/operations/README.md','docs/operations/CLIENT_LIFECYCLE.md','docs/onboarding/README.md','docs/onboarding/day_1_7_runbook.md','docs/checklists/README.md','docs/checklists/weekly.md','docs/checklists/monthly.md','docs/checklists/quarterly.md']),
('12-модель-пилота-и-готовность.md','Модель пилота, границы и готовность 8/10', '''Пилот ведут два человека в ограниченное время. Значит, лимит незавершённой работы и право отказать важнее широкого каталога услуг. Оценка 8/10 относится к ограниченному Bronze-пилоту и не доказывает готовность к критичной инфраструктуре.

Gate — условие, без которого переход запрещён. Evidence — проверяемое подтверждение: журнал, отчёт восстановления, результат внешнего скана, подписанное приложение. Зелёная CI-проверка не заменяет юридическую проверку и реальный restore.

Перед критичным клиентом нужны внешний scan после последнего firewall change, clean-room restore, измеренные RTO/RPO, проверка ПДн и договора юристом РФ, резервный инженер и тренировка P1.''',['docs/operations/PILOT_OPERATING_MODEL.md','docs/operations/LEGAL_AND_PRODUCTION_READINESS.md','docs/PROJECT_8_OF_10.md','docs/deployment/secrets_management.md']),
('13-экономика-и-выбор-тарифа.md','Экономика клиента и выбор тарифа', '''Единица расчёта — клиент-месяц. Выручка сама по себе не показывает выгоду. Из неё вычитаются инженерное время, время service manager, налог и банк, переменные сервисы и резерв на сбои. Остаток — contribution. Contribution margin равна contribution, делённому на выручку.

Тариф выбирается не по размеру компании, а по периметру, требуемому окну реакции, объёму инженерного времени, частоте restore drill и уровню координации. Bronze подходит небольшому ограниченному периметру и рабочему окну. Silver — большему числу узлов, квартальному review и более плотной эксплуатации. Gold — только критичному индивидуальному периметру после проверки ротации, права, DR и маржи.

Если клиент не помещается в лимит, уменьшают scope, повышают цену или отказывают. Скидка без уменьшения труда напрямую съедает contribution.''',['commercial/PRICING.md','commercial/ANALYSIS.md']),
('14-продажи-удержание-и-рост.md','Продажи, воронка и удержание клиента', '''Воронка — состояния с проверяемым входом и выходом. Действие продавца не равно прогрессу клиента. Discovery выясняет бизнес-влияние, владельца решения, сроки, бюджет, периметр и ограничения. Активная техническая проверка требует письменного разрешения.

КП связывает подтверждённую проблему с пакетом, исключениями, onboarding, ценой и следующим шагом. Gold проходит отдельный capacity gate. Если ресурсов нет, честный результат — waitlist или отказ.

Удержание начинается до договора: обещания должны совпасть с реальностью. После запуска работают ежемесячный отчёт, квартальный обзор, план рисков, результаты восстановления и понятный backlog. Продление обсуждают до конца срока, сравнивая ценность, фактические часы, маржу и изменившийся периметр.''',['commercial/README.md','commercial/SALES_FUNNEL.md','commercial/SALES_PLAYBOOK.md','commercial/PROPOSAL.md','commercial/ADS.md']),
('15-договор-sla-и-пдн.md','Договор, Order Form, SLA и персональные данные', '''MSA задаёт общие правила отношений. Order Form описывает конкретный тариф, периметр, цену и окно. SLA определяет измеримые обязательства. DPA регулирует порученную обработку персональных данных. Эти документы должны ссылаться на один и тот же scope.

Время реакции — начало работы, а не восстановление. RTO/RPO нельзя обещать выше подтверждённого тестом. Monitoring 24/7 не создаёт человеческое дежурство. Юридический шаблон остаётся шаблоном до проверки практикующим юристом РФ.

Перед подписью сопоставьте каждое обещание с техническим механизмом, владельцем, резервом и evidence.''',['contracts/README.md','contracts/MSP_SERVICE_AGREEMENT.md']),
('16-обучение-junior-и-передача.md','Обучение Junior и безопасная передача работы', '''Допуск выдаётся по доказанному навыку, а не по числу недель. L0 наблюдает, L1 действует при совместном экране, L2 выполняет одобренное изменение с reviewer, L3 самостоятельно ведёт ограниченные Bronze P2/P3.

Навык проверяется полным циклом: прочитать скрипт, назвать входы и побочные эффекты, выполнить на стенде, проверить результат, сделать откат и оформить evidence. Провал security-критерия означает повтор.

Передача владельца новому администратору уменьшает bus factor только тогда, когда второй человек реально восстанавливал систему, переносил MAX session и диагностировал почтовую ошибку.''',['docs/training/README.md','docs/training/JUNIOR_OPERATIONS_GUIDE.md','docs/training/DEPLOYMENT_MIGRATION_LABS.md']+[f'docs/training/week_{i:02d}.md' for i in range(1,13)]),
('17-сквозной-экзамен-владельца.md','Сквозной экзамен владельца', '''Экзамен связывает технику и бизнес. На чистой VM владелец разворачивает проект, объясняя каждый слой. Затем восстанавливает данные, отправляет заявку, получает Kaiten и email, вызывает тестовый P1 в MAX и оформляет сбой. После этого квалифицирует учебного клиента, выбирает тариф, считает маржу, готовит Order Form и план onboarding.

Работа не принята, если есть только команды без объяснения, backup без restore, alert без доставки, цена без стоимости времени или договор без проверенного capacity. Итоговый артефакт должен позволить другому допущенному человеку повторить процесс.''',['docs/PROJECT_8_OF_10.md','docs/training/DEPLOYMENT_MIGRATION_LABS.md','docs/operations/CLIENT_LIFECYCLE.md','commercial/PRICING.md'])]
for x in chapters: chapter(*x)

