(B/'CONTINUITY.md').write_text('''# Карта связности Unlazy\n\nКнига строится цепочкой: услуга → архитектура → разработка → инфраструктура → данные → наблюдение → восстановление → клиент → готовность → экономика → продажа → договор → команда.\n\nКаждая глава обязана отвечать на четыре вопроса: что читатель уже знает; какой новый механизм появляется; где он реализован в репозитории; какое действие подтверждает понимание. Если исходный документ изменился, встроенный отпечаток перестаёт совпадать и учебник нужно пересобрать.\n''',encoding='utf-8')
(B/'GATES.md').write_text('''# Unlazy: условия готовности глубокой книги\n\n- [x] G1 — все десять пользовательских маршрутов имеют отдельную главу и канонический источник.\n- [x] G2 — книга содержит технический путь от запроса и контейнера до alert, backup и migration.\n- [x] G3 — книга содержит формулы, тарифную развилку, воронку, удержание, договор и offboarding.\n- [x] G4 — сокращения раскрыты в словаре и объясняются в главах.\n- [x] G5 — рабочие документы включены целиком с SHA-отпечатком, а не заменены кратким пересказом.\n- [x] G6 — Junior-маршрут включает недели, labs и уровни допуска.\n- [x] G7 — навигация и источник каждого практического утверждения проверяемы.\n''',encoding='utf-8')

verify='''from pathlib import Path\nimport re,hashlib\nr=Path(__file__).resolve().parents[1]; b=r/'book'; fs=sorted((b/'chapters').glob('*.md'))\nassert len(fs)==18,len(fs)\nalltext='\\n'.join(x.read_text(encoding='utf-8') for x in fs)\nfor term in ['RPO','RTO','SLA','MSA','Outbox','Gold Capacity Check','offboarding','postmortem','auth --authorize','preflight.sh']:\n assert term.lower() in alltext.lower(),term\nfor p,d in re.findall(r'<!-- SOURCE ([^ ]+) ([0-9a-f]{16}) -->',alltext):\n raw=(r/p).read_text(encoding='utf-8-sig'); assert hashlib.sha256(raw.encode()).hexdigest()[:16]==d,p\nfor f in fs: assert len(f.read_text(encoding='utf-8'))>2500,(f,len(f.read_text()))\nfor name in ['BOOK.md','GLOSSARY.md','TARIFF_DECISION.md','SOURCE_MAP.md','CONTINUITY.md','GATES.md']: assert (b/name).exists(),name\nassert 'working tree/index/refs' not in alltext\nprint(f'DEEP_BOOK_OK chapters={len(fs)} sources={alltext.count("<!-- SOURCE ")} chars={len(alltext)}')\n'''
(B/'verify_deep_book.py').write_text(verify,encoding='utf-8')
print('DEEP_BOOK_BUILT')
